#!/usr/bin/env bash
# centraldark shared — alias curto da Casa. REUSE_BEFORE_CREATE.
# Uso: ./centraldark.sh SHARED  ou  ./centraldark.sh SHARED RESUME
set -euo pipefail
MODE="${1:-SHARED}"
if [ "$MODE" = "SHARED" ]; then
  echo "!CENTRALDARK RECONCILIAR_SHARED MISSION_ID=AUTO REPO=ServerVpss/CentralDark CANONICAL_BRANCH=main TRACE_MODE=SHARED ROLE=AUTO FIRST_WRITER_WINS=true ONE_WRITER_PER_SCOPE=true MULTI_READER=true PARALLELIZE_PERCEPTION=true SERIALIZE_MUTATION=true CURRENT_OVER_HISTORY=true FETCH_BEFORE_MEASURE=true REMEASURE_BEFORE_ACTION=true REUSE_BEFORE_CREATE=true ONE_SYSTEM_ONLY=true NO_V2_V3_V4=true DIRTY_WORKTREE=BLOCK NO_FORCE_PUSH=true NO_BLIND_OVERWRITE=true NO_RESET_DESTRUCTIVE=true UNKNOWN_IS_NOT_PASS=true ACTION_IS_NOT_PROOF=true SAME_HEAD_PROOF=true CLAIM_SEAL=true SAME_SIGNAL_WITHOUT_NEW_INFORMATION=DROP_DUPLICATE META_LUPA=CONTINUOUS MULTIBUSSOLA=CONTINUOUS VERTEX_INVERSO=ON CARACOL=UNTIL_FIXED_POINT FINAL_WRITER=FIRST_WRITER FINALIZE_ONLY_BY_PRIMARY_WRITER=true READERS_RETURN=DELTA+EVIDENCE_REF+OWNER+NEXT_CURSOR WRITER_ABSORBS_READERS=true FINAL_FLOW=REMEASURERECONCILETESTCOUNTERPROOFFIXED_POINTCOMMITPUSHPR_OR_MAINREMEASURERECEIPT BOOT=!CENTRALDARK#ACORDAR!CALIBRAR!MULTIBUSSOLA_META!META_LUPA!RECONCILIAR!CONTRAPROVA!VERTEX_INVERSO!CARACOL!FIXED_POINT!REGISTRA!BOOT"
  echo "[CENTRALDARK] Alias carregado. Writer original fecha a carreira. Nenhum V2."
elif [ "$MODE" = "RESUME" ]; then
  echo "!CENTRALDARK RECONCILIAR_SHARED RESUME_EXISTING_MISSION=true DISCOVER_ACTIVE_MISSION=true JOIN_EXISTING_TRACE=true DO_NOT_RESTART_PROVEN_WORK=true MISSION_ID=AUTO REPO=ServerVpss/CentralDark CANONICAL_BRANCH=main TRACE_MODE=SHARED ... (herdado)"
  echo "[CENTRALDARK] RESUME — role=READER se Writer existe; ACQUIRE_WRITER se não."
else
  echo "Uso: $0 SHARED | $0 SHARED RESUME"
  exit 1
fi
